  CK(cudaGetLastError());
  if (g_mask < 5) return 0;

  if (!P->useCL) {
    CB(cublasLtMatmul(g_lt, P->md2, &alpha, y, P->la2, w2h, P->lb2, &beta1, x, P->lc2, out, P->lc2, &P->h2[i2].algo,
