    CB(cublasLtMatmul(g_lt, P->md2, &alpha, w2h, P->la2, y, P->lb2, &beta0, d2, P->lc2, d2, P->lc2, &P->h2[i2].algo,
                      cw, kCublasWs, st));
    if (g_mask < 6) return 0;
    k4_transpose_add<<<dim3((P->HW + 31) / 32, (C + 31) / 32, B), dim3(32, 8), 0, st>>>(x, d2, out, P->HW, C);
